// ─── INPUTS ───────────────────────────────────────────────────────────────
const raw = $('Webhook Trigger').item.json;
const body = raw.body || raw;

const lead    = $('Get Lead Data').item.json;
const profile = $('Get Consultant Profile').item.json;

let templateHtml = null;
try {
  const t = $('Get Devis Template').item.json;
  if (t && t.html_css_content && t.html_css_content.length > 50) {
    templateHtml = t.html_css_content;
  }
} catch (e) { templateHtml = null; }

// ─── BRANDING ─────────────────────────────────────────────────────────────
const branding       = profile.branding_config || {};
const primaryColor   = branding.primaryColor  || '#48D951';
const accentColor    = branding.accentColor   || '#221A40';
const logo           = profile.company_logo_url || '';
const companyName    = profile.company_name   || 'Pretalk';
const consultantName = profile.full_name      || body.consultant_name || companyName;
const consultantEmail= profile.contact_email  || profile.email || body.consultant_email || '';
const consultantPhone= profile.phone          || '';
const consultantAddr = profile.address        || '';
const logoTag = logo
  ? '<img src="' + logo + '" class="doc-logo" alt="' + companyName + '" />'
  : '<span class="doc-brand-name">' + companyName + '</span>';

// ─── CLIENT INFO ──────────────────────────────────────────────────────────
const ri           = lead.respondent_info || {};
const clientName   = ri.name   || ri.firstName || 'Client';
const clientCompany= ri.company || ri.organization || '';
const clientEmail  = ri.email  || '';
const clientPhone  = ri.phone  || '';
const clientAddr   = ri.address || '';

// ─── QUOTE PAYLOAD ────────────────────────────────────────────────────────
const qtp = body.quote_template_payload || {};
const quoteItems    = qtp.quote_items || body.offer?.deliverables?.map((d, i) => ({
  description: d.name || d,
  quantity: 1,
  unit: 'forfait',
  unitPrice: (body.offer?.price_ht || 0) / Math.max((body.offer?.deliverables?.length || 1), 1),
})) || [];

const quoteNumber   = qtp.quote_number  || ('DEV-' + Date.now().toString().slice(-6));
const quoteSubject  = qtp.quote_subject || body.offer?.name || 'Proposition commerciale';
const validUntil    = qtp.valid_until   || new Date(Date.now() + 30 * 86400000).toLocaleDateString('fr-FR');
const paymentTerms  = qtp.payment_terms || '30 jours net';
const deliveryDelay = qtp.delivery_delay|| body.offer?.timeline || '4 à 6 semaines';
const quoteNotes    = qtp.notes         || '';
const locale        = body.locale       || 'fr';

const today = new Date().toLocaleDateString('fr-FR', { year: 'numeric', month: 'long', day: 'numeric' });

// ─── FINANCIAL CALCULATIONS ───────────────────────────────────────────────
const tvaRate = qtp.tva_rate ?? 20;
let subtotalHT = 0;
const quoteItemsRows = quoteItems.map((item) => {
  const qty   = Number(item.quantity || 1);
  const price = Number(item.unit_price ?? item.unitPrice ?? 0);
  const total = qty * price;
  subtotalHT += total;
  const fmtPrice = price.toLocaleString('fr-FR', { minimumFractionDigits: 2 }) + ' €';
  const fmtTotal = total.toLocaleString('fr-FR', { minimumFractionDigits: 2 }) + ' €';
  return (
    '<tr>' +
    '<td class="item-desc">' + (item.description || item.name || '') + '</td>' +
    '<td class="item-qty">'  + qty   + '</td>' +
    '<td class="item-unit">' + (item.unit || 'forfait') + '</td>' +
    '<td class="item-price">' + fmtPrice + '</td>' +
    '<td class="item-total">' + fmtTotal + '</td>' +
    '</tr>'
  );
}).join('');

const tvaMontant = subtotalHT * (tvaRate / 100);
const totalTTC   = subtotalHT + tvaMontant;

const fmtSubtotal = subtotalHT.toLocaleString('fr-FR', { minimumFractionDigits: 2 }) + ' €';
const fmtTVA      = tvaMontant.toLocaleString('fr-FR', { minimumFractionDigits: 2 }) + ' €';
const fmtTotal    = totalTTC.toLocaleString('fr-FR', { minimumFractionDigits: 2 }) + ' €';

// ─── REPLACE TEMPLATE VARS ────────────────────────────────────────────────
const rep = (html, key, val) =>
  html.replace(new RegExp('\\{\\{\\s*' + key + '\\s*\\}\\}', 'g'), String(val || ''));

let finalHtml;

if (templateHtml) {
  finalHtml = templateHtml;
  finalHtml = rep(finalHtml, 'primaryColor',   primaryColor);
  finalHtml = rep(finalHtml, 'accentColor',    accentColor);
  finalHtml = rep(finalHtml, 'logoTag',        logoTag);
  finalHtml = rep(finalHtml, 'companyName',    companyName);
  finalHtml = rep(finalHtml, 'consultantName', consultantName);
  finalHtml = rep(finalHtml, 'consultantEmail',consultantEmail);
  finalHtml = rep(finalHtml, 'consultantPhone',consultantPhone);
  finalHtml = rep(finalHtml, 'consultantAddress', consultantAddr);
  finalHtml = rep(finalHtml, 'clientName',    clientName);
  finalHtml = rep(finalHtml, 'clientCompany', clientCompany);
  finalHtml = rep(finalHtml, 'clientEmail',   clientEmail);
  finalHtml = rep(finalHtml, 'clientPhone',   clientPhone);
  finalHtml = rep(finalHtml, 'clientAddress', clientAddr);
  finalHtml = rep(finalHtml, 'date',          today);
  finalHtml = rep(finalHtml, 'quoteNumber',   quoteNumber);
  finalHtml = rep(finalHtml, 'quoteSubject',  quoteSubject);
  finalHtml = rep(finalHtml, 'validUntil',    validUntil);
  finalHtml = rep(finalHtml, 'paymentTerms',  paymentTerms);
  finalHtml = rep(finalHtml, 'deliveryDelay', deliveryDelay);
  finalHtml = rep(finalHtml, 'quoteNotes',    quoteNotes);
  finalHtml = rep(finalHtml, 'quoteItemsRows',quoteItemsRows);
  finalHtml = rep(finalHtml, 'subtotalHT',    fmtSubtotal);
  finalHtml = rep(finalHtml, 'tvaRate',       tvaRate + '%');
  finalHtml = rep(finalHtml, 'tvaMontant',    fmtTVA);
  finalHtml = rep(finalHtml, 'totalTTC',      fmtTotal);

  // Inject CSS vars override for colors
  const cssOverride = '<style>:root{--pc:' + primaryColor + ' !important;--ac:' + accentColor + ' !important;}</style>';
  finalHtml = finalHtml.includes('</head>')
    ? finalHtml.replace('</head>', cssOverride + '</head>')
    : cssOverride + finalHtml;

} else {
  // ─── FALLBACK MINIMAL HTML ──────────────────────────────────────────────
  finalHtml = `<!DOCTYPE html>
<html lang="fr">
<head>
<meta charset="UTF-8">
<style>
:root{--pc:${primaryColor};--ac:${accentColor};}
*,*::before,*::after{margin:0;padding:0;box-sizing:border-box}
html,body{font-family:Arial,sans-serif;font-size:10px;color:#1a1a2e;background:#fff;-webkit-print-color-adjust:exact;print-color-adjust:exact}
@page{size:5.8in 8.3in;margin:0}
.page{width:5.8in;min-height:8.3in;page-break-after:always;overflow:hidden;padding:0.5in}
.page:last-child{page-break-after:auto}
.hd{background:var(--ac);color:#fff;padding:0.3in 0.5in;margin:-0.5in -0.5in 0.3in;display:flex;justify-content:space-between;align-items:flex-end}
.hd-brand{font-size:11px;font-weight:900;text-transform:uppercase;letter-spacing:0.1em}
.hd-doc{text-align:right}
.hd-num{font-size:18px;font-weight:900}
.hd-date{font-size:8px;opacity:0.55;margin-top:2px}
.badge{background:var(--pc);color:var(--ac);font-size:7px;font-weight:900;letter-spacing:0.15em;text-transform:uppercase;padding:3px 8px;border-radius:2px;display:inline-block;margin-bottom:6px}
.parties{display:flex;gap:0.4in;margin:0.2in 0 0.3in}
.party{flex:1}
.party-label{font-size:7px;font-weight:700;letter-spacing:0.12em;text-transform:uppercase;color:var(--pc);border-bottom:1.5px solid var(--pc);padding-bottom:4px;margin-bottom:8px}
.party-name{font-size:10px;font-weight:700;color:var(--ac)}
.party-info{font-size:8px;color:#6b7280;margin-top:2px;line-height:1.5}
.subject{background:#f5f4fb;border-left:3px solid var(--pc);padding:10px 14px;border-radius:0 4px 4px 0;margin:0.2in 0}
.subject-label{font-size:7px;font-weight:700;text-transform:uppercase;letter-spacing:0.1em;color:var(--pc)}
.subject-text{font-size:11px;font-weight:700;color:var(--ac);margin-top:3px}
table{width:100%;border-collapse:collapse;margin:0.15in 0}
th{background:var(--ac);color:#fff;font-size:7.5px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;padding:7px 8px;text-align:left}
td{font-size:8.5px;padding:7px 8px;border-bottom:1px solid #e5e7eb}
tr:nth-child(even) td{background:#f9fafb}
.item-qty,.item-price,.item-total,.item-unit{text-align:right}
.totals{width:45%;margin-left:auto;margin-top:0.1in}
.tot-row{display:flex;justify-content:space-between;padding:5px 0;font-size:9px;border-bottom:1px solid #e5e7eb}
.tot-row.final{background:var(--ac);color:#fff;padding:8px 10px;font-weight:900;font-size:10px;border-radius:2px;margin-top:4px}
.footer-info{margin-top:0.2in;display:flex;gap:0.3in}
.footer-block{flex:1;font-size:8px;color:#6b7280}
.footer-block strong{display:block;font-size:7.5px;font-weight:700;text-transform:uppercase;letter-spacing:0.08em;color:var(--ac);margin-bottom:4px}
</style>
</head>
<body>
<div class="page">
  <div class="hd">
    <div class="hd-brand">${companyName}</div>
    <div class="hd-doc">
      <div class="badge">Devis</div>
      <div class="hd-num">${quoteNumber}</div>
      <div class="hd-date">${today}</div>
    </div>
  </div>
  <div class="parties">
    <div class="party">
      <div class="party-label">Émetteur</div>
      <div class="party-name">${consultantName}</div>
      <div class="party-info">${consultantEmail}${consultantPhone ? '<br>' + consultantPhone : ''}${consultantAddr ? '<br>' + consultantAddr : ''}</div>
    </div>
    <div class="party">
      <div class="party-label">Destinataire</div>
      <div class="party-name">${clientName}${clientCompany ? ' — ' + clientCompany : ''}</div>
      <div class="party-info">${clientEmail}${clientPhone ? '<br>' + clientPhone : ''}${clientAddr ? '<br>' + clientAddr : ''}</div>
    </div>
  </div>
  <div class="subject">
    <div class="subject-label">Objet du devis</div>
    <div class="subject-text">${quoteSubject}</div>
  </div>
  <table>
    <thead><tr>
      <th style="width:45%">Prestation</th>
      <th style="width:10%;text-align:right">Qté</th>
      <th style="width:12%;text-align:right">Unité</th>
      <th style="width:15%;text-align:right">P.U. HT</th>
      <th style="width:18%;text-align:right">Total HT</th>
    </tr></thead>
    <tbody>${quoteItemsRows || '<tr><td colspan="5" style="text-align:center;color:#9ca3af">Aucune prestation renseignée</td></tr>'}</tbody>
  </table>
  <div class="totals">
    <div class="tot-row"><span>Sous-total HT</span><span>${fmtSubtotal}</span></div>
    <div class="tot-row"><span>TVA (${tvaRate}%)</span><span>${fmtTVA}</span></div>
    <div class="tot-row final"><span>TOTAL TTC</span><span>${fmtTotal}</span></div>
  </div>
  <div class="footer-info">
    <div class="footer-block"><strong>Validité</strong>${validUntil}</div>
    <div class="footer-block"><strong>Délai de réalisation</strong>${deliveryDelay}</div>
    <div class="footer-block"><strong>Conditions de paiement</strong>${paymentTerms}</div>
  </div>
  ${quoteNotes ? '<div style="margin-top:0.15in;font-size:8px;color:#6b7280;border-top:1px solid #e5e7eb;padding-top:10px"><strong>Notes :</strong> ' + quoteNotes + '</div>' : ''}
</div>
</body></html>`;
}

const htmlBuffer = Buffer.from(finalHtml, 'utf8');
const binaryData = await this.helpers.prepareBinaryData(htmlBuffer, 'index.html', 'text/html');

const filename = 'devis_' + lead.id + '_' + Date.now() + '.pdf';

return [{
  json: {
    filename,
    lead_id: lead.id,
    user_id: body.user_id,
    quote_template_payload: qtp,
    offer_index: body.offer_index ?? 0,
    waitDelay: '2s',
  },
  binary: { html_file: binaryData },
}];

const supabaseUrl = 'https://htvtmrejzzwekztekzev.supabase.co';
const leadId   = $('Build Devis HTML').item.json.lead_id;
const filename = $('Build Devis HTML').item.json.filename;
const qtp      = $('Build Devis HTML').item.json.quote_template_payload;
const publicUrl = supabaseUrl + '/storage/v1/object/public/pdf-documents/devis/' + leadId + '/' + filename;
return { pdf_url: publicUrl, lead_id: leadId, filename, quote_template_payload: qtp };
